#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

static int lower(const int *a,int n,int target){
    int left=0,right=n;
    while(left<right){
        int middle=left+(right-left)/2;
        if(a[middle]<target) left=middle+1; else right=middle;
    }
    return left;
}
int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
int target;if(scanf("%d",&target)!=1)return 1;int i=lower(a,n,target);printf("%d\n",i<n && a[i]==target?i:-1);
return 0;
}
